package android.view;import android.content.Context;import java.util.*;public class ViewGroup extends View{public final List<View> children=new ArrayList<>();public ViewGroup(Context c){super(c);}public void addView(View v){children.add(v);}public void addView(View v,LayoutParams p){children.add(v);}public static class LayoutParams{public static final int MATCH_PARENT=-1,WRAP_CONTENT=-2;public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}}